їнською головне.", "answer": "Завтра день народження її племінника, прийде вся рідня.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Що в неї завтра?", "direction": "hr_ua", "points": [{"ua": "день народження племінника", "keys": [["племінник"]]}, {"ua": "прийде вся рідня", "keys": [["рідн"], ["родич"]]}], "hints": [], "models": ["Завтра день народження її племінника, прийде вся рідня."], "source_hr": "Sutra je rođendan mog nećaka. Dolazi cijela rodbina."}}, {"id": "ae8b5228-f928-556b-a304-0c404ba144f1", "lesson": "2b0e9742-99e1-57e1-a574-67ffb78d2607", "type": "write_message", "level": "A0", "skill": "writing", "question": "Напишіть мамі однокласника вашої дитини: запросіть її сина на день народження в суботу о 15:00 на дитячий майданчик біля школи.", "answer": "Pozivamo vašeg sina na rođendan u subotu u 15 sati, na igralište kod škole.", "task": {"situation_ua": "Напишіть мамі однокласника вашої дитини: запросіть її сина на день народження в суботу о 15:00 на дитячий майданчик біля школи.", "points": [{"ua": "запросіть", "keys": [["poziv"], ["pozv"], ["dođi"], ["dođe"]]}, {"ua": "на день народження", "keys": [["rođendan"]]}, {"ua": "коли", "keys": [["subot"], ["petnaest"], ["15"]]}, {"ua": "де", "keys": [["igrališt"], ["škol"]]}], "hints": ["pozivamo", "na rođendan", "u subotu", "igralište", "kod škole"], "models": ["Pozivamo vašeg sina na rođendan u subotu u 15 sati, na igralište kod škole."]}}, {"id": "145008fc-2128-5005-8031-7a489a56798e", "lesson": "2b0e9742-99e1-57e1-a574-67ffb78d2607", "type": "mediation", "level": "A0", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "У п’ятницю садочок зачинений, діти залишаються вдома.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Що пишуть із садочка?", "direction": "hr_ua", "points": [{"ua": "у п’ятницю садок зачинений", "keys": [["п''ятниц"]]}, {"ua": "діти лишаються вдома", "keys": [["вдома"], ["дома"]]}], "hints": [], "models": ["У п’ятницю садочок зачинений, діти залишаються вдома."], "source_hr": "Dragi roditelji, vrtić je u petak zatvoren. Djeca ostaju kod kuće."}}, {"id": "2eec45c3-9cd7-5e91-9442-42b3cbaada06", "lesson": "60130364-d731-5f5a-8b12-ac4d8d6d92e9", "type": "write_message", "level": "A0", "skill": "writing", "question": "Ви зустрічаєте Дашину подругу на вокзалі, але вона вас ніколи не бачила. Напишіть, як ви виглядаєте: зріст і волосся.", "answer": "Visoka sam i imam dugu plavu kosu.", "task": {"situation_ua": "Ви зустрічаєте Дашину подругу на вокзалі, але вона вас ніколи не бачила. Напишіть, як ви виглядаєте: зріст і волосся.", "points": [{"ua": "зріст", "keys": [["visok"], ["nizak"], ["nisk"]]}, {"ua": "волосся", "keys": [["kos"]]}, {"ua": "колір чи вигляд волосся", "keys": [["plav"], ["smeđ"], ["crn"], ["sijed"], ["kovrčav"], ["dug"], ["kratk"]]}], "hints": ["visok / visoka", "nizak / niska", "imam … kosu", "plavu", "smeđu", "kovrčavu"], "models": ["Visoka sam i imam dugu plavu kosu.", "Nizak sam, imam kratku smeđu kosu i bradu."]}}, {"id": "a84ebf14-1358-5413-af22-78517d8dcaae", "lesson": "60130364-d731-5f5a-8b12-ac4d8d6d92e9", "type": "mediation", "level": "A0", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Шукають терплячу, працьовиту й веселу няню з досвідом роботи з дітьми.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Яку няню вони шукають?", "direction": "hr_ua", "points": [{"ua": "терплячу", "keys": [["терпляч"]]}, {"ua": "працьовиту", "keys": [["працьовит"], ["старанн"]]}, {"ua": "з досвідом роботи з дітьми", "keys": [["досвід"]]}], "hints": [], "models": ["Шукають терплячу, працьовиту й веселу няню з досвідом роботи з дітьми."], "source_hr": "Tražimo dadilju: strpljivu, vrijednu i veselu, s iskustvom rada s djecom."}}, {"id": "9832570e-373d-5af6-9ea9-494ce8348724", "lesson": "40b9da1d-1686-5b78-8317-0439067d5f8e", "type": "write_message", "level": "A0", "skill": "writing", "question": "Ви їдете на вихідні. Ввічливо попросіть сусідку погодувати вашу кішку в суботу й неділю.", "answer": "Možete li, molim vas, hraniti moju mačku u subotu i nedjelju? Hvala!", "task": {"situation_ua": "Ви їдете на вихідні. Ввічливо попросіть сусідку погодувати вашу кішку в суботу й неділю.", "points": [{"ua": "ввічливо попросіть", "keys": [["molim"], ["možete li"], ["možeš li"]]}, {"ua": "погодувати", "keys": [["hran"]]}, {"ua": "кішку", "keys": [["mačk"], ["mačak"], ["mače"]]}, {"ua": "у суботу й неділю", "keys": [["subot"], ["nedjelj"], ["vikend"]]}], "hints": ["možete li", "hraniti", "moju mačku", "u subotu i nedjelju", "hvala"], "models": ["Možete li, molim vas, hraniti moju mačku u subotu i nedjelju? Hvala!"]}}, {"id": "56e68c16-fde6-520d-8b50-f6e3c9c3f6cf", "lesson": "40b9da1d-1686-5b78-8317-0439067d5f8e", "type": "mediation", "level": "A0", "skill": "mediation", "question": "Друг не знає хорватської. Перекажіть йому українською головне.", "answer": "Собак можна лише на повідку, і треба прибирати за своєю твариною.", "task": {"situation_ua": "Друг не знає хорватської. Перекажіть йому українською головне.", "friend_ua": "Що написано на табличці в парку?", "direction": "hr_ua", "points": [{"ua": "собак — лише на повідку", "keys": [["повід"]]}, {"ua": "прибирати за твариною", "keys": [["прибира"]]}], "hints": [], "models": ["Собак можна лише на повідку, і треба прибирати за своєю твариною."], "source_hr": "Psi samo na povodcu! Molimo, čistite za svojim ljubimcem."}}]'::jsonb)
      as t(id uuid, lesson uuid, type text, level text, skill text, question text, answer text, task jsonb)
  loop
    insert into public.exercises (id, exercise_type, question_text, correct_answer, options, level, order_index, status, task)
    values (r.id, r.type, r.question, r.answer, null, r.level, 0, 'PUBLISHED', r.task)
    on conflict (id) do nothing;
    if found then
      v_ex := v_ex + 1;
      insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
      values ('exercise', r.id, null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'writing 20261107 (a0_m02_m05): «Напишіть повідомлення» і «Перекажіть другу» (§57, §58), модулі A0.2–A0.5. Бета (рішення власника 2026-11-07), потрібна перевірка носієм.');
    end if;
    if not exists (select 1 from public.lesson_items where lesson_id = r.lesson and item_type = 'exercise' and item_id = r.id) then
      select coalesce(max(order_index), 0) + 1 into v_ord from public.lesson_items where lesson_id = r.lesson;
      insert into public.lesson_items (id, lesson_id, item_type, item_id, order_index, required, target_skill)
      values (gen_random_uuid(), r.lesson, 'exercise', r.id, v_ord, false, r.skill);
      v_items := v_items + 1;
    end if;
  end loop;

  -- Самоперевірка: у кожному уроці партії — рівно по одній вправі кожного типу з коректним завданням
  if exists (
    select 1 from unnest(array['2b6ed342-cc80-5bd9-baf0-b66109624d62'::uuid, '8abb83d8-ec02-5921-ac9b-814489816fcd'::uuid, '8f6439a9-c6ac-5271-99c8-1f0adc5d7599'::uuid, '04167753-db83-5163-a91c-9f71dac18ab5'::uuid, '479784bc-54ab-522d-9c77-55887ae68e33'::uuid, 'a9944193-2dfb-5944-b94c-41c41fdb7ca1'::uuid, 'adf335ee-0cba-5c9a-b86a-8baac868edbc'::uuid, '2fa5fa38-9641-5dc5-9156-6a3f7fe8035b'::uuid, '3b51b1bf-47f4-5709-96d9-c518d36440e6'::uuid, 'c0941bd8-57b5-5e7e-981f-9be423f24208'::uuid, 'e30c65f2-1a30-5b51-85e7-6a460cd1799f'::uuid, 'ffb92726-2fb1-5070-bf5c-5d2fb3b9393a'::uuid, 'c0d7b467-acb2-581a-975b-497e63f45aa7'::uuid, '1f41cb75-1ce5-57ba-a56f-58561ee1d983'::uuid, '40f7c64a-ad42-5fe2-a230-7b1e98607112'::uuid, 'ba35964d-f0d8-5d15-9566-ef44d37e6d12'::uuid, '22dd7878-4fa8-5e1c-909e-71c70ffd9918'::uuid, '4c5db9c0-aa58-55c5-b647-7f7cfc8396c2'::uuid, '427e5058-7381-58a0-8f21-bd170866dbae'::uuid, '8e372ece-ae10-50ae-9cf3-07b52ef2f72d'::uuid, '238d9508-3c2e-5ee6-910f-0ae8863c2dc7'::uuid, '39b1e31f-b573-5000-9713-1660688c3cc9'::uuid, '036fc4fb-1bf2-5100-9fd0-6f6a612554a1'::uuid, 'b36b4550-ff36-50cb-89fb-8246b351c8d6'::uuid, 'efcf49e0-c058-5986-9cf7-aee921887a81'::uuid, 'd7cf3059-0d92-5215-8ef4-ad699e317b10'::uuid, '4e003796-1ce0-5a02-8a2d-59a0de38f3dd'::uuid, '18efed0f-53a5-5717-9c4e-319627da2360'::uuid, 'f9ca38e4-3a61-56a6-b5f5-060933516c9a'::uuid, 'cec08ff0-a97d-5847-88cc-dee22fed2f8c'::uuid, '2b0e9742-99e1-57e1-a574-67ffb78d2607'::uuid, '60130364-d731-5f5a-8b12-ac4d8d6d92e9'::uuid, '40b9da1d-1686-5b78-8317-0439067d5f8e'::uuid]) as l(id), unnest(array['write_message', 'mediation']) as k(t)
    where (select count(*) from public.lesson_items li join public.exercises e on e.id = li.item_id
           where li.lesson_id = l.id and li.item_type = 'exercise' and e.exercise_type = k.t and e.status = 'PUBLISHED'
             and not li.required and jsonb_array_length(e.task -> 'points') between 1 and 5) <> 1) then
    raise exception 'Не в кожному уроці партії рівно одна вправа кожного типу';
  end if;
  raise notice 'Готово: письмо й переказ (модулі A0.2–A0.5) — вправ створено %, додано в уроки % (усього в партії 66)', v_ex, v_items;
end
